 <script>
+(()=>{
+const canvas=document.getElementById('world'),ctx=canvas.getContext('2d');
+const gravitySlider=document.getElementById('gravitySlider'),bounceSlider=document.getElementById('bounceSlider');
+const gravityRead=document.getElementById('gravityRead'),gravityValue=document.getElementById('gravityValue'),bounceValue=document.getElementById('bounceValue'),objectRead=document.getElementById('objectRead'),scoreRead=document.getElementById('scoreRead');
+const hint=document.getElementById('hint'),toast=document.getElementById('toast');
+let W=0,H=0,dpr=1,balls=[],planets=[],walls=[],stars=[],score=0,paused=false,tool='ball',pointer=null,showHint=true,lastTime=0,toastTimer;
+const rand=(a,b)=>a+Math.random()*(b-a), clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
+function resize(){const r=canvas.getBoundingClientRect();W=r.width;H=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);stars=stars.filter(s=>s.x<W-35&&s.y<H-35);while(stars.length<5-score)stars.push(makeStar());}
