+function addBall(x,y,vx=0,vy=0){if(balls.length>=45){say('That is a crowded universe!');return}balls.push({x,y,vx,vy,r:rand(12,18),hue:rand(175,218),trail:[]});updateHUD()}
+function onDown(e){e.preventDefault();const p=xy(e);canvas.setPointerCapture(e.pointerId);pointer={id:e.pointerId,start:p,end:p,moved:false};if(tool==='ball')pointer.aim=true;else if(tool==='wall')pointer.wall=true;else if(tool==='erase'){eraseAt(p.x,p.y);pointer=null}else if(tool==='planet'){planets.push({x:p.x,y:p.y,r:22,mass:1,phase:rand(0,6)});updateHUD();say('Planet placed · nearby balls will orbit');pointer=null;}}
+function onMove(e){if(!pointer||e.pointerId!==pointer.id)return;pointer.end=xy(e);pointer.moved=Math.hypot(pointer.end.x-pointer.start.x,pointer.end.y-pointer.start.y)>7}
+function onUp(e){if(!pointer||e.pointerId!==pointer.id)return;const q=pointer;pointer=null;if(q.aim){if(q.moved){const dx=q.start.x-q.end.x,dy=q.start.y-q.end.y,mag=Math.hypot(dx,dy)||1;addBall(q.start.x,q.start.y,dx/mag*Math.min(17,mag*.13),dy/mag*Math.min(17,mag*.13));}else addBall(q.start.x,q.start.y,rand(-1,1),rand(-1,1));hideHint()}else if(q.wall&&q.moved){const x=Math.min(q.start.x,q.end.x),y=Math.min(q.start.y,q.end.y),w=Math.abs(q.end.x-q.start.x),h=Math.abs(q.end.y-q.start.y);if(w>12||h>12){walls.push({x,y,w:Math.max(w,18),h:Math.max(h,18)});updateHUD()}else say('Drag to draw a wall');}}
