document.getElementById('helpBtn').addEventListener('click',()=>say('Choose a tool, then tap or drag in the universe. Collect all 5 stars!'));
const dust=Array.from({length:85},()=>({x:Math.random(),y:Math.random(),a:rand(.15,.55),s:rand(.5,1.7)}));
function collideWalls(b){for(const a of walls){const nx=clamp(b.x,a.x,a.x+a.w),ny=clamp(b.y,a.y,a.y+a.h),dx=b.x-nx,dy=b.y-ny;if(dx*dx+dy*dy<b.r*b.r){if(Math.abs(dx)>Math.abs(dy)){b.x=dx>0?a.x+a.w+b.r:a.x-b.r;b.vx=Math.abs(b.vx)*Math.sign(dx||1)*.78}else{b.y=dy>0?a.y+a.h+b.r:a.y-b.r;b.vy=Math.abs(b.vy)*Math.sign(dy||1)*.78}}}}
function step(dt){const scale=Math.min(dt/16.67,2.1),g=Number(gravitySlider.value)*.22,bounce=Number(bounceSlider.value)/100;
for(const b of balls){b.trail.push({x:b.x,y:b.y});if(b.trail.length>10)b.trail.shift();b.vy+=g*scale;
for(const p of planets){const dx=p.x-b.x,dy=p.y-b.y,d2=dx*dx+dy*dy,dist=Math.sqrt(d2)||1;if(dist>p.r+2){const force=Math.min(.48, (p.mass*34/(d2+260))*scale);b.vx+=dx/dist*force;b.vy+=dy/dist*force}}
b.x+=b.vx*scale;b.y+=b.vy*scale;b.vx*=Math.pow(.999,scale);b.vy*=Math.pow(.999,scale);
if(b.x<b.r){b.x=b.r;b.vx=Math.abs(b.vx)*bounce}if(b.x>W-b.r){b.x=W-b.r;b.vx=-Math.abs(b.vx)*bounce}if(b.y<b.r){b.y=b.r;b.vy=Math.abs(b.vy)*bounce}if(b.y>H-b.r){b.y=H-b.r;b.vy=-Math.abs(b.vy)*bounce;if(Math.abs(b.vy)<.7)b.vy=0}collideWalls(b);
}
for(let i=0;i<balls.length;i++)for(let j=i+1;j<balls.length;j++){const a=balls[i],b=balls[j],dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy),min=a.r+b.r;if(d>0&&d<min){const nx=dx/d,ny=dy/d,over=min-d;a.x-=nx*over*.5;a.y-=ny*over*.5;b.x+=nx*over*.5;b.y+=ny*over*.5;const rel=(b.vx-a.vx)*nx+(b.vy-a.vy)*ny;if(rel<0){const impulse=-(1+bounce)*rel*.5;a.vx-=impulse*nx;a.vy-=impulse*ny;b.vx+=impulse*nx;b.vy+=impulse*ny}}}
for(let i=stars.length-1;i>=0;i--){const s=stars[i];for(const b of balls)if(Math.hypot(b.x-s.x,b.y-s.y)<b.r+12){stars.splice(i,1);score++;updateHUD();say(score>=5?'✨ Star master! You cleared the universe!':'Star collected! Keep going.');if(score<5)stars.push(makeStar());break}}
}
function pathStar(x,y,r){ctx.beginPath();for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,rr=i%2?r*.42:r;const px=x+Math.cos(a)*rr,py=y+Math.sin(a)*rr;i?ctx.lineTo(px,py):ctx.moveTo(px,py)}ctx.closePath()}
function draw(t){ctx.clearRect(0,0,W,H);const bg=ctx.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#101a32');bg.addColorStop(.55,'#0c1427');bg.addColorStop(1,'#0a1120');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
ctx.save();for(const d of dust){ctx.globalAlpha=d.a;ctx.fillStyle='#bad6ff';ctx.beginPath();ctx.arc(d.x*W,d.y*H,d.s,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
ctx.strokeStyle='#8ba9dc0d';ctx.lineWidth=1;const stepSize=42,off=(t*.008)%stepSize;for(let x=0;x<W;x+=stepSize){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=-stepSize;y<H+stepSize;y+=stepSize){ctx.beginPath();ctx.moveTo(0,y+off);ctx.lineTo(W,y+off);ctx.stroke()}
for(const s of stars){const pulse=1+Math.sin(t*.004+s.phase)*.12;ctx.shadowColor='#ffd36a';ctx.shadowBlur=22;pathStar(s.x,s.y,12*pulse);ctx.fillStyle='#ffda78';ctx.fill();ctx.shadowBlur=0;ctx.beginPath();ctx.arc(s.x,s.y,19*pulse,0,Math.PI*2);ctx.strokeStyle='#ffd36a25';ctx.stroke()}
for(const a of walls){const grad=ctx.createLinearGradient(a.x,a.y,a.x+a.w,a.y+a.h);grad.addColorStop(0,'#415270');grad.addColorStop(.5,'#273750');grad.addColorStop(1,'#1a263b');ctx.fillStyle=grad;ctx.strokeStyle='#91b4d568';ctx.lineWidth=1;ctx.beginPath();ctx.roundRect(a.x,a.y,a.w,a.h,5);ctx.fill();ctx.stroke();ctx.strokeStyle='#c0d8ff25';ctx.beginPath();ctx.moveTo(a.x+4,a.y+3);ctx.lineTo(a.x+a.w-4,a.y+3);ctx.stroke()}
for(const p of planets){const pulse=1+Math.sin(t*.002+p.phase)*.035;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(-.35);ctx.strokeStyle='#bd91ff88';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(0,0,p.r*1.65,p.r*.56,0,0,Math.PI*2);ctx.stroke();ctx.restore();const glow=ctx.createRadialGradient(p.x,p.y,2,p.x,p.y,p.r*2.7);glow.addColorStop(0,'#c7a2ff55');glow.addColorStop(1,'#b68bff00');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(p.x,p.y,p.r*2.7,0,Math.PI*2);ctx.fill();const pg=ctx.createRadialGradient(p.x-p.r*.35,p.y-p.r*.4,2,p.x,p.y,p.r*pulse);pg.addColorStop(0,'#f1deff');pg.addColorStop(.3,'#bd91ff');pg.addColorStop(1,'#56427e');ctx.fillStyle=pg;ctx.beginPath();ctx.arc(p.x,p.y,p.r*pulse,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#e6d6ff88';ctx.lineWidth=1.2;ctx.stroke()}
for(const b of balls){for(let i=0;i<b.trail.length;i++){const q=b.trail[i],alpha=i/b.trail.length*.22;ctx.fillStyle=`hsla(${b.hue},95%,70%,${alpha})`;ctx.beginPath();ctx.arc(q.x,q.y,b.r*i/b.trail.length*.72,0,Math.PI*2);ctx.fill()}ctx.shadowColor=`hsla(${b.hue},100%,65%,.6)`;ctx.shadowBlur=18;const gr=ctx.createRadialGradient(b.x-b.r*.38,b.y-b.r*.42,1,b.x,b.y,b.r);gr.addColorStop(0,'#f4fdff');gr.addColorStop(.18,`hsl(${b.hue},90%,83%)`);gr.addColorStop(.62,`hsl(${b.hue},88%,62%)`);gr.addColorStop(1,`hsl(${b.hue},70%,38%)`);ctx.fillStyle=gr;ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#ffffff82';ctx.lineWidth=1;ctx.stroke()}
if(pointer){if(pointer.aim){const dx=pointer.start.x-pointer.end.x,dy=pointer.start.y-pointer.end.y,mag=Math.hypot(dx,dy);ctx.strokeStyle='#83e6ffbb';ctx.lineWidth=2;ctx.setLineDash([5,5]);ctx.beginPath();ctx.moveTo(pointer.start.x,pointer.start.y);ctx.lineTo(pointer.start.x+dx,pointer.start.y+dy);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#83e6ff';ctx.beginPath();ctx.arc(pointer.start.x,pointer.start.y,13,0,Math.PI*2);ctx.strokeStyle='#83e6ff88';ctx.stroke()}else if(pointer.wall){ctx.fillStyle='#91b4d624';ctx.strokeStyle='#90cfff';ctx.setLineDash([5,4]);ctx.beginPath();ctx.roundRect(Math.min(pointer.start.x,pointer.end.x),Math.min(pointer.start.y,pointer.end.y),Math.max(1,Math.abs(pointer.end.x-pointer.start.x)),Math.max(1,Math.abs(pointer.end.y-pointer.start.y)),5);ctx.fill();ctx.stroke();ctx.setLineDash([])}}
ctx.restore();}
function frame(now){const dt=lastTime?Math.min(now-lastTime,34):16;lastTime=now;if(!paused)step(dt);draw(now);requestAnimationFrame(frame)}
new ResizeObserver(resize).observe(canvas);resize();reset();requestAnimationFrame(frame);
})();
</script>
</body>
</html>

